<?php
function nexa_backup_dir(): string { $d=rtrim((string)($GLOBALS['config']['abs']??dirname(__DIR__,3)),'/').'/content/backup'; if(!is_dir($d)) @mkdir($d,0755,true); return $d; }
function nexa_backup_create(): ?string { $root=rtrim((string)($GLOBALS['config']['abs']??dirname(__DIR__,3)),'/'); $name='nexa-backup-'.date('Ymd-His').'.zip'; $zip=new ZipArchive(); if($zip->open(nexa_backup_dir().'/'.$name,ZipArchive::CREATE)!==true) return null; $add=function($dir,$prefix) use (&$add,$zip){ foreach(scandir($dir)?:[] as $f){ if($f==='.'||$f==='..') continue; $full=$dir.'/'.$f; if(is_dir($full)) $add($full,$prefix.$f.'/'); elseif(is_file($full) && filesize($full)<20*1024*1024) $zip->addFile($full,$prefix.$f); } }; if(is_dir($root.'/admin/database')) $add($root.'/admin/database','database/'); if(is_file($root.'/config.php')) $zip->addFile($root.'/config.php','config.php'); $zip->close(); return $name; }
